begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function pg_temp.expect_state(query text,expected text) returns void language plpgsql as $$ begin begin execute query; exception when others then if sqlstate=expected then raise notice 'PASS: rejection %',expected;return; end if;raise;end;raise exception 'Expected SQLSTATE %',expected;end $$;
select pg_temp.assert_true(to_regclass('private.performance_reviews') is not null,'native review storage exists');
select pg_temp.assert_true((select count(*)=3 and bool_and(relrowsecurity and relforcerowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('performance_reviews','performance_review_events','performance_review_operations')),'all three tables force RLS');
select pg_temp.assert_true(not exists(select 1 from (values ('anon'),('authenticated'),('service_role')) r(role) cross join (values ('private.performance_reviews'),('private.performance_review_events'),('private.performance_review_operations')) t(tbl) where has_table_privilege(r.role,t.tbl,'SELECT,INSERT,UPDATE,DELETE')),'no browser or service direct table grants');
