update public.profiles set app_role='hr' where id='a1000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","iat":1900000000}',true);
select pg_temp.expect_state('select public.performance_review_workspace()','42501');
reset role;
rollback to legacy_role;
savepoint rls_fault;
grant select on private.performance_reviews to authenticated;
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from private.performance_reviews),'forced RLS still denies rows under an explicit synthetic ACL fault');
reset role;
rollback to rls_fault;
do $$ declare i integer; candidate jsonb; begin
  for i in 0..11 loop
    candidate:=jsonb_set(to_jsonb(array_fill('Evidence'::text,array[12])),array[i::text],'""');
    perform pg_temp.assert_true(private.performance_review_answers(candidate,true)=(i not in (0,3,4,5,6,7,8,9,10)),'native required answer index '||i);
    candidate:=jsonb_set(current_setting('test.manager_input')::jsonb,array['ratings',i::text],'""');
    perform pg_temp.assert_true(private.performance_review_manager_input(candidate,true)=(i not in (0,1,2,6,7,8,9)),'native required rating index '||i);
  end loop;
end $$;
select pg_temp.expect_state($q$select private.performance_review_meeting_end('{"date":"2026-01-02","time":"10:00","duration":4,"mode":"phone","location":"Synthetic","notes":""}',false)$q$,'22023');
select pg_temp.expect_state($q$select private.performance_review_meeting_end('{"date":"2026-01-02","time":"10:00","duration":481,"mode":"phone","location":"Synthetic","notes":""}',false)$q$,'22023');
select pg_temp.assert_true(private.performance_review_meeting_end('{"date":"2026-01-02","time":"10:00","duration":480,"mode":"phone","location":"Synthetic","notes":""}',false)='2026-01-02T07:00:00Z'::timestamptz,'native 480 minute upper boundary');
select pg_temp.assert_true(private.performance_review_meeting_end('{"date":"2026-01-02","time":"10:00","duration":5,"mode":"phone","location":"Synthetic","notes":""}',false)='2026-01-01T23:05:00Z'::timestamptz,'native five minute lower boundary');
rollback;
